const dateFromToday = days => {
  const date = new Date();
  date.setUTCHours(0, 0, 0, 0);
  date.setUTCDate(date.getUTCDate() + days);
  return date.toISOString().slice(0, 10);
};

// Fictional records only. Replace this array or connect another credential-free input.
const invoices = [
  {
    invoiceId: 'INV-FICTION-1001',
    customer: { id: 'CUST-FICTION-01', name: 'Northstar Demo GmbH', email: 'billing@northstar-demo.example', phone: '' },
    currency: 'EUR',
    totalAmount: 1200,
    paidAmount: 0,
    outstandingAmount: 1200,
    dueDate: dateFromToday(2),
    paymentStatus: 'unpaid',
    disputed: false,
    updatedAt: new Date().toISOString(),
  },
  {
    invoiceId: 'INV-FICTION-1002',
    customer: { id: 'CUST-FICTION-02', name: 'Riverbank Sample SAS', email: '', phone: '+33 1 00 00 00 00' },
    currency: 'EUR',
    totalAmount: 500,
    paidAmount: 0,
    outstandingAmount: 500,
    dueDate: dateFromToday(-8),
    paymentStatus: 'unpaid',
    disputed: false,
    updatedAt: new Date().toISOString(),
  },
  {
    invoiceId: 'INV-FICTION-1003',
    customer: { id: 'CUST-FICTION-03', name: 'Orchard Example Ltd', email: 'accounts@orchard-example.example', phone: '' },
    currency: 'GBP',
    totalAmount: 800,
    paidAmount: 800,
    outstandingAmount: 0,
    dueDate: dateFromToday(-5),
    paymentStatus: 'paid',
    disputed: false,
    updatedAt: new Date().toISOString(),
  },
];

return invoices.map(invoice => ({ json: invoice }));

const UPCOMING_DAYS_BEFORE_DUE = 3;
const OVERDUE_STAGES = [
  { stage: 'overdue_3_days', minimumDaysOverdue: 3 },
  { stage: 'overdue_7_days', minimumDaysOverdue: 7 },
  { stage: 'overdue_14_days', minimumDaysOverdue: 14 },
];
const EVALUATION_DATE = ''; // Optional YYYY-MM-DD test override; blank uses the current UTC date.
const AMOUNT_TOLERANCE = 0.01;

const raw = $json ?? {};
const text = (value, max = 200) => String(value ?? '').trim().replace(/\s+/g, ' ').slice(0, max);
const invoiceId = text(raw.invoiceId);
const customerId = text(raw.customer?.id);
const customerName = text(raw.customer?.name);
const email = text(raw.customer?.email, 320).toLowerCase();
const phoneDigits = text(raw.customer?.phone, 50).replace(/\D/g, '');
const phone = phoneDigits.startsWith('00') ? `+${phoneDigits.slice(2)}` : phoneDigits ? `+${phoneDigits.replace(/^\+/, '')}` : '';
const currency = text(raw.currency, 3).toUpperCase();
const paymentStatus = text(raw.paymentStatus, 40).toLowerCase().replace(/[ -]+/g, '_');
const disputed = raw.disputed === true || String(raw.disputed).toLowerCase() === 'true';
const totalAmount = Number(raw.totalAmount);
const paidAmount = Number(raw.paidAmount);
const outstandingAmount = Number(raw.outstandingAmount);
const sourceUpdatedAt = text(raw.updatedAt, 40);
const dueDate = text(raw.dueDate, 10);
const errors = [];
const reviewReasons = [];

const parseDateOnly = value => {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return null;
  const date = new Date(`${value}T00:00:00.000Z`);
  return Number.isNaN(date.getTime()) || date.toISOString().slice(0, 10) !== value ? null : date;
};

if (!invoiceId) errors.push('invoice_id_missing');
if (!customerId || !customerName) errors.push('customer_identity_missing');
if (!/^[A-Z]{3}$/.test(currency)) errors.push('currency_invalid');
if (![totalAmount, paidAmount, outstandingAmount].every(Number.isFinite)) errors.push('amount_invalid');
if ([totalAmount, paidAmount, outstandingAmount].some(value => Number.isFinite(value) && value < 0)) errors.push('amount_negative');
const due = parseDateOnly(dueDate);
if (!due) errors.push('due_date_invalid');
if (!['unpaid', 'paid', 'partially_paid'].includes(paymentStatus)) errors.push('payment_status_invalid');

let classification = 'invalid';
let reminderStage = '';
let outputPath = 'invalid_record';
let actionReason = errors.join(',');

if (errors.length === 0) {
  const inconsistentAmount = Math.abs(totalAmount - paidAmount - outstandingAmount) > AMOUNT_TOLERANCE;
  const paidConflict = paymentStatus === 'paid' && outstandingAmount > AMOUNT_TOLERANCE;
  const unpaidConflict = paymentStatus === 'unpaid' && (paidAmount > AMOUNT_TOLERANCE || outstandingAmount <= AMOUNT_TOLERANCE);
  const partialByAmount = paidAmount > AMOUNT_TOLERANCE && outstandingAmount > AMOUNT_TOLERANCE;

  if (inconsistentAmount) reviewReasons.push('amounts_inconsistent');
  if (paidConflict || unpaidConflict) reviewReasons.push('payment_state_conflict');
  if (!email && !phone) reviewReasons.push('customer_contact_missing');

  if (disputed) {
    classification = 'disputed';
    reviewReasons.push('invoice_disputed');
  } else if (paymentStatus === 'partially_paid' || partialByAmount) {
    classification = 'partially_paid';
    reviewReasons.push('partial_payment');
  } else if (reviewReasons.length > 0) {
    classification = 'requiring_manual_review';
  } else if (paymentStatus === 'paid' && outstandingAmount <= AMOUNT_TOLERANCE) {
    classification = 'paid';
    outputPath = 'no_action_required';
    actionReason = 'invoice_paid';
  } else {
    const evaluation = parseDateOnly(EVALUATION_DATE) ?? parseDateOnly(new Date().toISOString().slice(0, 10));
    const daysUntilDue = Math.round((due.getTime() - evaluation.getTime()) / 86400000);

    if (daysUntilDue > 0) {
      classification = 'upcoming';
      if (daysUntilDue <= UPCOMING_DAYS_BEFORE_DUE) reminderStage = `upcoming_${UPCOMING_DAYS_BEFORE_DUE}_days`;
      else actionReason = 'outside_upcoming_interval';
    } else if (daysUntilDue === 0) {
      classification = 'due';
      reminderStage = 'due_today';
    } else {
      classification = 'overdue';
      const daysOverdue = Math.abs(daysUntilDue);
      reminderStage = [...OVERDUE_STAGES].reverse().find(stage => daysOverdue >= stage.minimumDaysOverdue)?.stage ?? '';
      if (!reminderStage) actionReason = 'before_first_overdue_interval';
    }

    if (reminderStage) {
      outputPath = 'ready_for_review';
      actionReason = 'reminder_stage_eligible';
    } else {
      outputPath = 'no_action_required';
    }
  }

  if (reviewReasons.length > 0) {
    outputPath = 'manual_review';
    actionReason = [...new Set(reviewReasons)].join(',');
    reminderStage = '';
  }
}

const preparedAt = new Date().toISOString();
const draft = reminderStage ? {
  reminderStage,
  recipient: { customerId, customerName, email, phone },
  subject: `Payment reminder review: invoice ${invoiceId}`,
  title: `Review ${reminderStage} for ${invoiceId}`,
  messageVariables: { invoiceId, customerName, currency, totalAmount, paidAmount, outstandingAmount, dueDate },
  invoice: { invoiceId, currency, totalAmount, paidAmount, outstandingAmount, dueDate, paymentStatus, disputed },
  reviewStatus: 'pending_manual_approval',
} : null;

return { json: { invoiceId, customerId, customerName, email, phone, currency, totalAmount, paidAmount, outstandingAmount, dueDate, paymentStatus, disputed, sourceUpdatedAt, classification, reminderStage, outputPath, actionReason, preparedAt, draft } };

const seen = new Set();
return $input.all().map((item, index) => {
  const value = item.json;
  if (value.outputPath !== 'ready_for_review') return item;
  const key = `${value.invoiceId}::${value.reminderStage}`;
  if (!seen.has(key)) {
    seen.add(key);
    return item;
  }
  return { json: { ...value, outputPath: 'already_prepared', actionReason: 'duplicate_in_execution', reviewStatus: 'already_prepared', historyRecordId: null }, pairedItem: { item: index } };
});

const historyByKey = new Map();

for (const item of $('Load Reminder History').all()) {
  const row = item.json ?? {};
  const invoiceId = String(row.invoice_id ?? '').trim();
  const reminderStage = String(row.reminder_stage ?? '').trim();
  if (!invoiceId || !reminderStage || row.id === undefined || row.id === null) continue;

  const key = `${invoiceId}::${reminderStage}`;
  const current = historyByKey.get(key);
  if (!current || String(row.prepared_at ?? '') > String(current.prepared_at ?? '')) historyByKey.set(key, row);
}

return $input.all().map((item, index) => {
  const invoice = item.json;
  if (invoice.outputPath !== 'ready_for_review') return item;

  const key = `${invoice.invoiceId}::${invoice.reminderStage}`;
  const history = historyByKey.get(key);
  if (!history) return item;

  return {
    json: {
      ...invoice,
      outputPath: 'already_prepared',
      actionReason: 'reminder_stage_already_prepared',
      reviewStatus: 'already_prepared',
      historyRecordId: history.id,
      previousPreparedAt: history.prepared_at ?? null,
    },
    pairedItem: { item: index },
  };
});

const invoiceByKey = new Map(
  $('Check Reminder History').all()
    .map(item => item.json)
    .filter(invoice => invoice.outputPath === 'ready_for_review')
    .map(invoice => [`${invoice.invoiceId}::${invoice.reminderStage}`, invoice]),
);

return $input.all().map((item, index) => {
  const row = item.json ?? {};
  const key = `${String(row.invoice_id ?? '').trim()}::${String(row.reminder_stage ?? '').trim()}`;
  const invoice = invoiceByKey.get(key);
  if (!invoice) throw new Error(`No prepared invoice matches history row ${key}`);

  return {
    json: {
      ...invoice,
      historyRecordId: row.id ?? null,
      outputPath: 'ready_for_review',
      reviewStatus: 'pending_manual_approval',
      deliveryEnabled: false,
    },
    pairedItem: { item: index },
  };
});
